<?php
declare(strict_types=1);require_once __DIR__.'/../includes/bootstrap.php';admin_required();$connection=db();$summary=$connection->query("SELECT COUNT(*) orders,COALESCE(SUM(CASE WHEN DATE(created_at)=CURDATE() AND status='completed' THEN total_amount END),0) daily,COALESCE(SUM(CASE WHEN YEAR(created_at)=YEAR(CURDATE()) AND MONTH(created_at)=MONTH(CURDATE()) AND status='completed' THEN total_amount END),0) monthly FROM orders")->fetch_assoc();$status=$connection->query('SELECT status,COUNT(*) count FROM orders GROUP BY status')->fetch_all(MYSQLI_ASSOC);$best=$connection->query("SELECT product_name,SUM(quantity) sold,SUM(quantity*unit_price) value FROM order_items GROUP BY product_id,product_name ORDER BY sold DESC LIMIT 10")->fetch_all(MYSQLI_ASSOC);$inventory=$connection->query('SELECT COALESCE(SUM(price*stock_quantity),0) value FROM products')->fetch_assoc();
?><!doctype html><html><head><meta charset="utf-8"><title>Reports | Sammy Tech</title><link rel="stylesheet" href="../assets/css/admin.css"></head><body><div class="admin-layout"><aside><a class="admin-brand" href="index.php"><span>ST</span> SAMMY TECH</a><a href="index.php">Overview</a><a href="catalog.php">Catalog</a><a class="side-active" href="reports.php">Reports</a></aside><main class="admin-main"><header><div><p class="eyebrow">Business reporting</p><h1>Sales snapshot.</h1></div><button onclick="window.print()" class="add-link">Print report</button></header><section class="stat-grid"><article><span>Orders</span><strong><?=e((string)$summary['orders'])?></strong></article><article><span>Daily sales</span><strong><?=money((float)$summary['daily'])?></strong></article><article><span>Monthly sales</span><strong><?=money((float)$summary['monthly'])?></strong></article><article><span>Inventory value</span><strong><?=money((float)$inventory['value'])?></strong></article></section><section class="catalog-layout"><section class="panel"><div class="panel-title"><h2>Orders by status</h2></div><?php foreach($status as $row):?><p><?=e(ucfirst($row['status']))?><b style="float:right"><?=e((string)$row['count'])?></b></p><?php endforeach;?></section><section class="panel"><div class="panel-title"><h2>Best-selling products</h2></div><table><thead><tr><th>Product</th><th>Qty sold</th><th>Value</th></tr></thead><tbody><?php foreach($best as $row):?><tr><td><?=e($row['product_name'])?></td><td><?=e((string)$row['sold'])?></td><td><?=money((float)$row['value'])?></td></tr><?php endforeach;?></tbody></table></section></section></main></div></body></html>
